import { supabase, supabaseSetupMessage } from "./supabase";

// Ideas are generated by the Supabase Edge Function `generate-ideas`, which
// holds GEMINI_API_KEY as a function secret. The browser never sees a provider
// key or URL; it only receives the three structured ideas.
export async function requestIdeas(brief) {
  if (!supabase) throw new Error(supabaseSetupMessage);

  const { data, error } = await supabase.functions.invoke("generate-ideas", {
    body: brief,
  });

  if (error) {
    let message = "";
    const response = error.context;
    if (response && typeof response.json === "function") {
      const payload = await response.json().catch(() => null);
      if (typeof payload?.error === "string" && payload.error.trim()) {
        message = payload.error.trim();
      }
    }
    if (message) throw new Error(message);
    if (error.name === "FunctionsFetchError") {
      throw new Error("Could not reach the idea service. Check your connection and try again.");
    }
    throw new Error("The idea service is unavailable right now. Try again.");
  }

  if (!Array.isArray(data?.ideas) || data.ideas.length !== 3) {
    throw new Error("The idea service returned an unexpected response. Try again.");
  }

  return data.ideas;
}
